UPDATE pms_sku_stock s INNER JOIN (
SELECT #{item.productSkuId} AS sid, #{item.productQuantity} AS qty
) t ON s.id = t.sid SET s.stock = s.stock - t.qty, s.lock_stock = s.lock_stock - t.qty WHERE s.stock >= t.qty AND s.lock_stock >= t.qty

UPDATE pms_sku_stock s INNER JOIN (
SELECT #{item.productSkuId} AS sid, #{item.productQuantity} AS qty
) t ON s.id = t.sid SET s.lock_stock = s.lock_stock - t.qty WHERE s.lock_stock >= t.qty


UPDATE pms_sku_stock
SET lock_stock = lock_stock + #{quantity}
WHERE id = #{skuId}
  AND (stock - lock_stock) >= #{quantity}
